import{_ as e,c as a,o as r,ag as n}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Desktop Administrator","description":"Using the desktop Administrator client","frontmatter":{"title":"Desktop Administrator","description":"Using the desktop Administrator client"},"headers":[],"relativePath":"engine/desktop_administrator.md","filePath":"engine/desktop_administrator.md","lastUpdated":1788476353000}'),s={name:"engine/desktop_administrator.md"};function o(i,t,d,l,h,c){return r(),a("div",null,t[0]||(t[0]=[n('<h1 id="desktop-administrator" tabindex="-1">Desktop Administrator <a class="header-anchor" href="#desktop-administrator" aria-label="Permalink to &quot;Desktop Administrator&quot;">​</a></h1><p>The Administrator is a Java-based desktop application for managing and configuring your OIE server. It provides a graphical interface for building channels, monitoring message traffic, managing users, and adjusting server settings.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>As of 4.6.0 this is no longer the only graphical option. The <a href="./web_administrator.html">Web Administrator</a> does the same job in a browser, and both can be pointed at the same engine at the same time.</p></div><p>Starting the client and logging in are covered in <a href="./accessing_the_administrator.html">Accessing the Administrator</a>. It connects to the server over HTTPS on port <code>8443</code> by default.</p><h2 id="interface-layout" tabindex="-1">Interface layout <a class="header-anchor" href="#interface-layout" aria-label="Permalink to &quot;Interface layout&quot;">​</a></h2><p>The Administrator window is divided into several key regions:</p><table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title Bar</strong></td><td>Displays the server name and OIE version</td></tr><tr><td><strong>View Title</strong></td><td>Shows the name of the active view (e.g. &quot;Dashboard&quot;)</td></tr><tr><td><strong>Main Navigation</strong></td><td>A list of top-level views on the left side: Dashboard, Channels, Users, Settings, Alerts, Events, Extensions. The highlighted item indicates which view is currently active.</td></tr><tr><td><strong>Context Tasks</strong></td><td>Action buttons below the navigation that change depending on the current view (e.g. Deploy, Start, Stop when on the Dashboard)</td></tr><tr><td><strong>Other Tasks</strong></td><td>A fixed set of utility links available from every view: Notifications, View User API, View Client API, Help, About, Logout</td></tr><tr><td><strong>Content Area</strong></td><td>The main panel on the right side where the selected view is displayed</td></tr><tr><td><strong>Status Bar</strong></td><td>Shows the server connection URL, logged-in user, and server time with timezone at the bottom of the window</td></tr><tr><td><strong>Progress Bar</strong></td><td>Indicates background task progress in the bottom-right corner</td></tr></tbody></table><h2 id="working-with-tables" tabindex="-1">Working with tables <a class="header-anchor" href="#working-with-tables" aria-label="Permalink to &quot;Working with tables&quot;">​</a></h2><p>Many screens in the Administrator display data in configurable tables. The following interactions are available across most table views:</p><ul><li><strong>Rearrange columns</strong>. Drag a column header to a new position. Adjacent columns shift automatically.</li><li><strong>Show or hide columns</strong>. Right-click the header row and toggle column visibility, or use the table control icon in the top-right corner of the table.</li><li><strong>Sort data</strong>. Click a column header to sort ascending; click again for descending. Not all tables support sorting.</li><li><strong>Expand or collapse rows</strong>. Click the plus/minus icon next to a row, or right-click the header and choose Expand All / Collapse All.</li><li><strong>Select multiple rows</strong>. Hold Shift and click for a contiguous range. Hold Ctrl (or Cmd on macOS) and click for individual non-contiguous rows.</li><li><strong>Search within the table</strong>. Press Ctrl+F (or Cmd+F) to open a find dialog that locates and highlights matching rows.</li><li><strong>Delete a row</strong>. Select the row and press the Delete key (where the table supports deletion).</li></ul><h2 id="key-views" tabindex="-1">Key views <a class="header-anchor" href="#key-views" aria-label="Permalink to &quot;Key views&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>The first screen you see after logging in. It shows all deployed channels with their current state, message counts, and connection activity. From here you can start, stop, pause, and undeploy channels.</p><p>See <a href="./dashboard_and_monitoring.html">Dashboard and Monitoring</a> for full details.</p><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><p>The main management screen for every channel configured on the server. You can create, delete, import, export, clone, enable, disable, and deploy channels. Channels are organized into groups, and you can filter by name or tag.</p><h3 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h3><p>Displays all user accounts that can access the server, whether through the Administrator, the CLI, or the REST API. You can add, edit, and remove users from this view.</p><p>See <a href="./user_management.html">User Management</a> for full details.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>A tabbed configuration area covering server-wide options:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td>Server name, usage statistics preference, default queue buffer size, default metadata columns, and SMTP email configuration</td></tr><tr><td><strong>Administrator</strong></td><td>UI preferences such as dashboard refresh interval and confirmation dialog behavior</td></tr><tr><td><strong>Tags</strong></td><td>Create and manage channel tags</td></tr><tr><td><strong>Configuration Map</strong></td><td>Key-value pairs accessible from channel scripts at runtime</td></tr><tr><td><strong>Database Tasks</strong></td><td>View and manage pending or completed database migration tasks</td></tr><tr><td><strong>Resources</strong></td><td>Custom class-path library resources available to channels</td></tr><tr><td><strong>Data Pruner</strong></td><td>Global settings for automatic message pruning</td></tr></tbody></table><h3 id="alerts" tabindex="-1">Alerts <a class="header-anchor" href="#alerts" aria-label="Permalink to &quot;Alerts&quot;">​</a></h3><p>Lists all configured alerts with their enabled/disabled status and the number of times each has fired. From here you can create, edit, import, export, enable, and disable alerts.</p><p>See <a href="./alerts_and_notifications.html">Alerts and Notifications</a> for full details.</p><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h3><p>A searchable log of user actions and system events: logins, channel deployments, configuration changes, server startup/shutdown, data pruner activity, and more. Events can be filtered by date, severity level, user, outcome, and other criteria, and exported to CSV.</p><h3 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h3><p>Shows all installed plugins and connectors with their status, author, and version. You can enable or disable individual extensions from this view.</p><h2 id="channel-editor" tabindex="-1">Channel Editor <a class="header-anchor" href="#channel-editor" aria-label="Permalink to &quot;Channel Editor&quot;">​</a></h2><p>Opening a channel for editing brings up a multi-tabbed workspace:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Summary</strong></td><td>Channel name, description, data types, initial state, storage and pruning settings, tags, dependencies, and custom metadata columns</td></tr><tr><td><strong>Source</strong></td><td>Source connector type and its settings</td></tr><tr><td><strong>Destinations</strong></td><td>One or more destination connectors, each with their own filter and transformer configuration</td></tr><tr><td><strong>Scripts</strong></td><td>Channel-level scripts: Deploy, Undeploy, Preprocessor, and Postprocessor</td></tr></tbody></table><h3 id="transformer-and-filter-editors" tabindex="-1">Transformer and filter editors <a class="header-anchor" href="#transformer-and-filter-editors" aria-label="Permalink to &quot;Transformer and filter editors&quot;">​</a></h3><p>Within the Source and Destinations tabs, you can open dedicated editors for building filters and transformers:</p><ul><li><strong>Filter Editor</strong>. Define rules (Rule Builder, JavaScript, External Script) connected by AND/OR operators. Messages matching the criteria are accepted; others are rejected.</li><li><strong>Transformer Editor</strong>. Build a sequence of steps (Mapper, Message Builder, JavaScript, External Script, XSLT, Iterator, Destination Set Filter) to reshape message content. The inbound and outbound message trees let you drag fields to auto-generate mapping steps.</li></ul><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for full details.</p><h2 id="message-browser" tabindex="-1">Message Browser <a class="header-anchor" href="#message-browser" aria-label="Permalink to &quot;Message Browser&quot;">​</a></h2><p>Select a channel on the Dashboard and choose <strong>View Messages</strong> (or double-click the channel) to open the Message Browser. This view lets you inspect every message that has passed through the channel, including all content snapshots (Raw, Transformed, Encoded, Sent, Response), variable mappings, errors, and attachments.</p><p>Key capabilities:</p><ul><li>Search by date range, message status, connector, text content, and custom metadata</li><li>View all content types for any connector message</li><li>Import, export, reprocess, and remove messages</li><li>Inspect error details and stack traces</li></ul><p>See <a href="./dashboard_and_monitoring.html">Dashboard and Monitoring</a> for full details on the Message Browser.</p><h2 id="other-tasks" tabindex="-1">Other tasks <a class="header-anchor" href="#other-tasks" aria-label="Permalink to &quot;Other tasks&quot;">​</a></h2><p>The bottom-left section of every view provides a set of global utility links:</p><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Notifications</strong></td><td>Displays OIE release announcements fetched from the project&#39;s GitHub repository. New unread items trigger a count badge.</td></tr><tr><td><strong>View User API</strong></td><td>Opens the User API (Javadoc) documentation in your browser</td></tr><tr><td><strong>View Client API</strong></td><td>Opens the REST API documentation in your browser</td></tr><tr><td><strong>Help</strong></td><td>Opens the OIE GitHub discussions in your browser</td></tr><tr><td><strong>About</strong></td><td>Shows version, build date, server ID, Java version, and third-party software acknowledgements</td></tr><tr><td><strong>Logout</strong></td><td>Ends your session and returns to the login screen</td></tr></tbody></table>',44)]))}const p=e(s,[["render",o]]);export{u as __pageData,p as default};
